import{_ as o,o as s,c as t,Q as a}from"./chunks/framework.b67c47e6.js";const e="/assets/api-token-dialog.018071e3.svg",E=JSON.parse('{"title":"API v2","description":"","frontmatter":{},"headers":[],"relativePath":"guide/api/index.md","filePath":"guide/api/index.md","lastUpdated":1790346505000}'),n={name:"guide/api/index.md"},l=a('<h1 id="api-v2" tabindex="-1">API v2 <a class="header-anchor" href="#api-v2" aria-label="Permalink to &quot;API v2&quot;">​</a></h1><p>The produuz.it REST API lets you automate design uploads, constructible management, report generation, and more from external systems.</p><nav class="table-of-contents"><ul><li><a href="#interactive-documentation">Interactive Documentation</a></li><li><a href="#authentication">Authentication</a><ul><li><a href="#api-accounts">API accounts</a></li></ul></li><li><a href="#pagination">Pagination</a></li><li><a href="#main-endpoint-groups">Main Endpoint Groups</a></li><li><a href="#common-workflows">Common Workflows</a></li><li><a href="#material-quantities-for-purchasing">Material Quantities for Purchasing</a></li><li><a href="#rate-limits">Rate Limits</a></li></ul></nav><h2 id="interactive-documentation" tabindex="-1">Interactive Documentation <a class="header-anchor" href="#interactive-documentation" aria-label="Permalink to &quot;Interactive Documentation&quot;">​</a></h2><p>The full API is documented through an interactive Swagger interface:</p><ul><li><strong>Swagger UI:</strong> <a href="https://back.produuz.it/api/v2/auth/login/?next=/api/v2/swagger/" target="_blank" rel="noreferrer">back.produuz.it/api/v2/swagger/</a></li><li><strong>OpenAPI schema:</strong> <a href="https://back.produuz.it/api/v2/auth/login/?next=/api/v2/openapi/" target="_blank" rel="noreferrer">back.produuz.it/api/v2/openapi/</a>, for importing into API clients.</li></ul><p>Both links go through the produuz.it login page first. The schema only lists the endpoints your account can use, so sign in to see all of them.</p><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><p>The API uses <strong>JWT (JSON Web Token)</strong> authentication.</p><ol><li><strong>Obtain a token pair</strong> — <code>POST /api/v2/my_user/token/</code> with <code>username</code> and <code>password</code>. If the account has two-factor authentication (2FA) enabled, also send the current code as <code>otp</code>. The response holds an <code>access</code> and a <code>refresh</code> token.</li><li><strong>Include the access token</strong> — add <code>Authorization: Bearer &lt;access&gt;</code> to every request.</li><li><strong>Refresh the access token</strong> — <code>POST /api/v2/my_user/token/refresh/</code> with <code>{&quot;refresh&quot;: &quot;&lt;refresh&gt;&quot;}</code> returns a new <code>access</code> token.</li></ol><p>An access token is valid for 1 hour. A refresh token from the login endpoint is valid for 10 hours.</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#E1E4E8;">{ </span><span style="color:#79B8FF;">&quot;username&quot;</span><span style="color:#E1E4E8;">: </span><span style="color:#9ECBFF;">&quot;jan&quot;</span><span style="color:#E1E4E8;">, </span><span style="color:#79B8FF;">&quot;password&quot;</span><span style="color:#E1E4E8;">: </span><span style="color:#9ECBFF;">&quot;********&quot;</span><span style="color:#E1E4E8;">, </span><span style="color:#79B8FF;">&quot;otp&quot;</span><span style="color:#E1E4E8;">: </span><span style="color:#9ECBFF;">&quot;123456&quot;</span><span style="color:#E1E4E8;"> }</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292E;">{ </span><span style="color:#005CC5;">&quot;username&quot;</span><span style="color:#24292E;">: </span><span style="color:#032F62;">&quot;jan&quot;</span><span style="color:#24292E;">, </span><span style="color:#005CC5;">&quot;password&quot;</span><span style="color:#24292E;">: </span><span style="color:#032F62;">&quot;********&quot;</span><span style="color:#24292E;">, </span><span style="color:#005CC5;">&quot;otp&quot;</span><span style="color:#24292E;">: </span><span style="color:#032F62;">&quot;123456&quot;</span><span style="color:#24292E;"> }</span></span></code></pre></div><p>A missing code answers <code>400</code> with <code>{&quot;otp&quot;: &quot;OTP needed for this user&quot;}</code>, a wrong one with <code>{&quot;otp_invalid&quot;: &quot;OTP not valid&quot;}</code>.</p><h3 id="api-accounts" tabindex="-1">API accounts <a class="header-anchor" href="#api-accounts" aria-label="Permalink to &quot;API accounts&quot;">​</a></h3><p>For machine-to-machine integrations, use an <strong>API account</strong> instead of a person&#39;s account. API accounts have no password and do not log in: a company admin generates their tokens in the app.</p><ol><li>In <strong>Company settings</strong>, open the <strong>API Accounts</strong> card and press <strong>New</strong>. Give it an <strong>Account label</strong> (up to 10 characters) and a <strong>Role</strong>. The number of API accounts is limited by your licence, and the counter is shown on the card (<code>1/3 API Accounts</code>).</li><li>On the account row, press the key button. In <strong>Get Tokens for API Account</strong>, set <strong>Days to expiracy</strong> (7 by default, at most 370) and press <strong>Load</strong>.</li><li>Copy the <strong>Refresh Token</strong> and the <strong>Access Token</strong>. Store the refresh token safely and use it with <code>/api/v2/my_user/token/refresh/</code> to get a new access token every hour.</li></ol><p><img src="'+e+`" alt="The API Accounts card and the token dialog"></p><ol><li>The key button on the account row opens <strong>Get Tokens for API Account</strong>.</li><li>How many days the refresh token stays valid.</li><li>After <strong>Load</strong>, the refresh token and, below it, the access token. Click one to copy it.</li></ol><p>Only company admins can generate tokens. The role of the API account decides what it can do, exactly like a user: an integration that creates or changes data needs the <strong>Company Manager</strong> or <strong>Company Admin</strong> role.</p><h2 id="pagination" tabindex="-1">Pagination <a class="header-anchor" href="#pagination" aria-label="Permalink to &quot;Pagination&quot;">​</a></h2><p>List endpoints are paginated: the response is an object with <code>count</code>, <code>next</code>, <code>previous</code> and <code>results</code>, 100 rows per page by default. Use the <code>limit</code> and <code>offset</code> query parameters to page through them, or follow <code>next</code> until it is <code>null</code>.</p><h2 id="main-endpoint-groups" tabindex="-1">Main Endpoint Groups <a class="header-anchor" href="#main-endpoint-groups" aria-label="Permalink to &quot;Main Endpoint Groups&quot;">​</a></h2><table><thead><tr><th>Group</th><th>Base path</th><th>Description</th></tr></thead><tbody><tr><td><strong>Constructibles</strong></td><td><code>/api/v2/constructibles/</code></td><td>Designs, actuals (assemblies/modules), batches, parts, part batches</td></tr><tr><td><strong>Company</strong></td><td><code>/api/v2/company/</code></td><td>Projects, standard libraries, contacts, users, IFC parsing setups, API accounts</td></tr><tr><td><strong>My company</strong></td><td><code>/api/v2/my_company/</code></td><td>Your company and its settings</td></tr><tr><td><strong>Reports</strong></td><td><code>/api/v2/reports/</code></td><td>Report creation and status tracking</td></tr><tr><td><strong>Tools</strong></td><td><code>/api/v2/tools/</code></td><td>Tool jobs, such as the Mobfile Generator</td></tr><tr><td><strong>Factories</strong></td><td><code>/api/v2/factories/</code></td><td>Production lines, stations, machines, triggers, action setups</td></tr><tr><td><strong>Cloud Storage</strong></td><td><code>/api/v2/cloudstorage/</code></td><td>File uploads and package management</td></tr><tr><td><strong>Logistics</strong></td><td><code>/api/v2/logistics/</code></td><td>Materials, products, sizes, racks and rack loads</td></tr><tr><td><strong>Records</strong></td><td><code>/api/v2/records/</code></td><td>Issues, production events, production proofs</td></tr><tr><td><strong>Dashboard</strong></td><td><code>/api/v2/dashboard/</code></td><td>Dashboard indicators</td></tr><tr><td><strong>Integrations</strong></td><td><code>/api/v2/integrations/</code></td><td>Webhooks</td></tr><tr><td><strong>User</strong></td><td><code>/api/v2/my_user/</code></td><td>Profile, authentication, settings</td></tr></tbody></table><h2 id="common-workflows" tabindex="-1">Common Workflows <a class="header-anchor" href="#common-workflows" aria-label="Permalink to &quot;Common Workflows&quot;">​</a></h2><p>For step-by-step API tutorials, see <a href="/tutorials/api/">Connecting to the API</a>:</p><ul><li><a href="/tutorials/api/post_designs/">Upload and create designs</a></li><li><a href="/tutorials/api/designs/">Fetch and filter designs</a></li><li><a href="/tutorials/api/constructibles/">Generate constructibles</a></li><li><a href="/tutorials/api/reports/">Generate reports and machine files</a></li><li><a href="/tutorials/api/ifc_to_mob2/">IFC to MOB2 file, end to end</a></li></ul><h2 id="material-quantities-for-purchasing" tabindex="-1">Material Quantities for Purchasing <a class="header-anchor" href="#material-quantities-for-purchasing" aria-label="Permalink to &quot;Material Quantities for Purchasing&quot;">​</a></h2><p>To order material you don&#39;t need to download every part. Ask the sizes endpoint for the material in scope and let it count for you:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#e1e4e8;">POST /api/v2/logistics/sizes/profiles/names_and_actual_dims/</span></span>
<span class="line"><span style="color:#e1e4e8;">POST /api/v2/logistics/sizes/plates/names_and_actual_dims/</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292e;">POST /api/v2/logistics/sizes/profiles/names_and_actual_dims/</span></span>
<span class="line"><span style="color:#24292e;">POST /api/v2/logistics/sizes/plates/names_and_actual_dims/</span></span></code></pre></div><p>The scope goes in the body as uuid lists, which are OR-ed together. Any of <code>projects</code>, <code>assemblies</code>, <code>part_batches</code> and <code>modules</code> works. Add <code>with_counts</code> to get the quantities:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#E1E4E8;">{ </span><span style="color:#79B8FF;">&quot;projects&quot;</span><span style="color:#E1E4E8;">: [</span><span style="color:#9ECBFF;">&quot;&lt;project uuid&gt;&quot;</span><span style="color:#E1E4E8;">], </span><span style="color:#79B8FF;">&quot;with_counts&quot;</span><span style="color:#E1E4E8;">: </span><span style="color:#79B8FF;">true</span><span style="color:#E1E4E8;"> }</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292E;">{ </span><span style="color:#005CC5;">&quot;projects&quot;</span><span style="color:#24292E;">: [</span><span style="color:#032F62;">&quot;&lt;project uuid&gt;&quot;</span><span style="color:#24292E;">], </span><span style="color:#005CC5;">&quot;with_counts&quot;</span><span style="color:#24292E;">: </span><span style="color:#005CC5;">true</span><span style="color:#24292E;"> }</span></span></code></pre></div><p>Each entry is one material size with its cut dimensions. For profiles the dimension is the cut length in mm; for plates it is <code>length*width</code>:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#E1E4E8;">[{</span></span>
<span class="line"><span style="color:#E1E4E8;">  </span><span style="color:#79B8FF;">&quot;size&quot;</span><span style="color:#E1E4E8;">: </span><span style="color:#9ECBFF;">&quot;VUREN_C24 38*120&quot;</span><span style="color:#E1E4E8;">,</span></span>
<span class="line"><span style="color:#E1E4E8;">  </span><span style="color:#79B8FF;">&quot;actual_dims&quot;</span><span style="color:#E1E4E8;">: [</span><span style="color:#9ECBFF;">&quot;5630&quot;</span><span style="color:#E1E4E8;">, </span><span style="color:#9ECBFF;">&quot;5380&quot;</span><span style="color:#E1E4E8;">],</span></span>
<span class="line"><span style="color:#E1E4E8;">  </span><span style="color:#79B8FF;">&quot;dims&quot;</span><span style="color:#E1E4E8;">: [</span></span>
<span class="line"><span style="color:#E1E4E8;">    {</span><span style="color:#79B8FF;">&quot;dim&quot;</span><span style="color:#E1E4E8;">: </span><span style="color:#9ECBFF;">&quot;5630&quot;</span><span style="color:#E1E4E8;">, </span><span style="color:#79B8FF;">&quot;count&quot;</span><span style="color:#E1E4E8;">: </span><span style="color:#79B8FF;">2</span><span style="color:#E1E4E8;">, </span><span style="color:#79B8FF;">&quot;total_length&quot;</span><span style="color:#E1E4E8;">: </span><span style="color:#79B8FF;">11260.0</span><span style="color:#E1E4E8;">},</span></span>
<span class="line"><span style="color:#E1E4E8;">    {</span><span style="color:#79B8FF;">&quot;dim&quot;</span><span style="color:#E1E4E8;">: </span><span style="color:#9ECBFF;">&quot;5380&quot;</span><span style="color:#E1E4E8;">, </span><span style="color:#79B8FF;">&quot;count&quot;</span><span style="color:#E1E4E8;">: </span><span style="color:#79B8FF;">4</span><span style="color:#E1E4E8;">, </span><span style="color:#79B8FF;">&quot;total_length&quot;</span><span style="color:#E1E4E8;">: </span><span style="color:#79B8FF;">21520.0</span><span style="color:#E1E4E8;">}</span></span>
<span class="line"><span style="color:#E1E4E8;">  ],</span></span>
<span class="line"><span style="color:#E1E4E8;">  </span><span style="color:#79B8FF;">&quot;count&quot;</span><span style="color:#E1E4E8;">: </span><span style="color:#79B8FF;">148</span><span style="color:#E1E4E8;">,</span></span>
<span class="line"><span style="color:#E1E4E8;">  </span><span style="color:#79B8FF;">&quot;total_length&quot;</span><span style="color:#E1E4E8;">: </span><span style="color:#79B8FF;">115766.0</span></span>
<span class="line"><span style="color:#E1E4E8;">}]</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292E;">[{</span></span>
<span class="line"><span style="color:#24292E;">  </span><span style="color:#005CC5;">&quot;size&quot;</span><span style="color:#24292E;">: </span><span style="color:#032F62;">&quot;VUREN_C24 38*120&quot;</span><span style="color:#24292E;">,</span></span>
<span class="line"><span style="color:#24292E;">  </span><span style="color:#005CC5;">&quot;actual_dims&quot;</span><span style="color:#24292E;">: [</span><span style="color:#032F62;">&quot;5630&quot;</span><span style="color:#24292E;">, </span><span style="color:#032F62;">&quot;5380&quot;</span><span style="color:#24292E;">],</span></span>
<span class="line"><span style="color:#24292E;">  </span><span style="color:#005CC5;">&quot;dims&quot;</span><span style="color:#24292E;">: [</span></span>
<span class="line"><span style="color:#24292E;">    {</span><span style="color:#005CC5;">&quot;dim&quot;</span><span style="color:#24292E;">: </span><span style="color:#032F62;">&quot;5630&quot;</span><span style="color:#24292E;">, </span><span style="color:#005CC5;">&quot;count&quot;</span><span style="color:#24292E;">: </span><span style="color:#005CC5;">2</span><span style="color:#24292E;">, </span><span style="color:#005CC5;">&quot;total_length&quot;</span><span style="color:#24292E;">: </span><span style="color:#005CC5;">11260.0</span><span style="color:#24292E;">},</span></span>
<span class="line"><span style="color:#24292E;">    {</span><span style="color:#005CC5;">&quot;dim&quot;</span><span style="color:#24292E;">: </span><span style="color:#032F62;">&quot;5380&quot;</span><span style="color:#24292E;">, </span><span style="color:#005CC5;">&quot;count&quot;</span><span style="color:#24292E;">: </span><span style="color:#005CC5;">4</span><span style="color:#24292E;">, </span><span style="color:#005CC5;">&quot;total_length&quot;</span><span style="color:#24292E;">: </span><span style="color:#005CC5;">21520.0</span><span style="color:#24292E;">}</span></span>
<span class="line"><span style="color:#24292E;">  ],</span></span>
<span class="line"><span style="color:#24292E;">  </span><span style="color:#005CC5;">&quot;count&quot;</span><span style="color:#24292E;">: </span><span style="color:#005CC5;">148</span><span style="color:#24292E;">,</span></span>
<span class="line"><span style="color:#24292E;">  </span><span style="color:#005CC5;">&quot;total_length&quot;</span><span style="color:#24292E;">: </span><span style="color:#005CC5;">115766.0</span></span>
<span class="line"><span style="color:#24292E;">}]</span></span></code></pre></div><ul><li><code>count</code> is the number of parts to cut. Deprecated parts — replaced or deleted work — are not counted, so the quantities are orderable as they come.</li><li>Totals come as <code>total_length</code> in mm for profiles and <code>total_area</code> in mm2 for plates.</li><li>Without <code>with_counts</code> you get only <code>size</code> and <code>actual_dims</code>, which is the cheaper call for filling in a material selector.</li><li><code>with_counts</code> needs a scope: counting a whole company catalogue is rejected with a <code>400</code>.</li><li>Scope by <code>projects</code>, <code>assemblies</code> or <code>part_batches</code>. A part inside a panel that sits inside a module is only linked to the panel, so scoping by <code>modules</code> alone can miss parts.</li></ul><h2 id="rate-limits" tabindex="-1">Rate Limits <a class="header-anchor" href="#rate-limits" aria-label="Permalink to &quot;Rate Limits&quot;">​</a></h2><p>The REST API has no general rate limit. Only the Claude connector (MCP) endpoints are limited: 600 requests per hour on <code>/api/v2/mcp</code> and 120 per hour on <code>/api/v2/mcp/docs</code>. Over the limit, they answer <code>429 Too Many Requests</code>; wait before retrying.</p>`,36),r=[l];function p(c,i,d,u,h,y){return s(),t("div",null,r)}const m=o(n,[["render",p]]);export{E as __pageData,m as default};
